import { ChangeDetectionStrategy, Component, computed, inject } from '@angular/core';
import { Router, RouterLink } from '@angular/router';
import { Home, LucideAngularModule } from 'lucide-angular';

import { LedgerStore } from '../../../services/ledger-store/ledger.store';

/**
 * Metadata for a single breadcrumb item.
 */
export interface IBreadcrumb {
    href: string;
    label: string;
    isLast: boolean;
}

/**
 * Map of route segments to their human-readable labels.
 */
const routeLabels: Record<string, string> = {
    accounts: 'Accounts',
    payees: 'Payees',
    settings: 'Settings',
    'style-guide': 'Style Guide',
    dev: 'Developer Tools',
    'sync-test': 'Sync Test',
    auth: 'Authentication',
    info: 'Information',
};

/**
 * Breadcrumb navigation component that dynamically resolves labels based on the current URL.
 */
@Component({
    selector: 'app-breadcrumb-nav',
    standalone: true,
    imports: [RouterLink, LucideAngularModule],
    templateUrl: './breadcrumb-nav.component.html',
    styleUrl: './breadcrumb-nav.component.css',
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class BreadcrumbNavComponent {
    private readonly router: Router = inject(Router);
    private readonly ledgerStore: LedgerStore = inject(LedgerStore);

    readonly HomeIcon = Home;

    /**
     * Computed signal that builds the breadcrumb list from the current URL.
     */
    readonly breadcrumbs = computed((): Array<IBreadcrumb> => {
        const url: string = this.router.url.split('?')[0] ?? '';
        const segments: Array<string> = url.split('/').filter(Boolean);

        if (segments.length < 2) {
            return new Array<IBreadcrumb>();
        }

        return segments.map((segment: string, index: number): IBreadcrumb => {
            const href: string = `/${segments.slice(0, index + 1).join('/')}`;
            const isLast: boolean = index === segments.length - 1;

            let label: string = routeLabels[segment] ?? segment;

            // Resolve account ID to name if in accounts path
            if (segments[index - 1] === 'accounts') {
                const account = this.ledgerStore.accounts().find(a => a.id === segment);
                if (account) {
                    label = account.name;
                }
            }

            // Capitalize if no specific label found
            if (label === segment) {
                label = segment.charAt(0).toUpperCase() + segment.slice(1);
            }

            return { href, label, isLast } satisfies IBreadcrumb;
        });
    });
}

import { ChangeDetectionStrategy, Component, computed, input } from '@angular/core';
import { type IProjectionDataPoint, Money } from '@path-logic/core';

/**
 * Interface for internal coordinate mapping.
 */
interface IChartPoint {
    x: number;
    y: number;
    balance: number;
    date: string;
}

/**
 * Premium SVG-based cashflow projection chart.
 * Ported from React Sim-X visualization. Uses Angular signals for reactive rendering.
 */
@Component({
    selector: 'app-projection-chart',
    standalone: true,
    imports: [],
    templateUrl: './projection-chart.component.html',
    styleUrl: './projection-chart.component.css',
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ProjectionChartComponent {
    /**
     * 90-day projection data points.
     */
    readonly data = input<Array<IProjectionDataPoint>>(new Array<IProjectionDataPoint>());

    /**
     * Component height in pixels.
     * @default 200
     */
    readonly height = input<number>(200);

    /**
     * Additional CSS classes for the container.
     */
    readonly className = input<string>('');

    /**
     * Maps data points to 0-100 normalized SVG coordinates.
     */
    readonly points = computed((): Array<IChartPoint> => {
        const dataArr: Array<IProjectionDataPoint> = this.data();
        if (dataArr.length === 0) return new Array<IChartPoint>();

        const balances: Array<number> = dataArr.map(
            (d: IProjectionDataPoint): number => d.projectedBalance,
        );
        const min: number = Math.min(...balances);
        const max: number = Math.max(...balances);
        const range: number = max - min || 1;

        return dataArr.map(
            (d: IProjectionDataPoint, i: number): IChartPoint =>
                ({
                    x: (i / (dataArr.length - 1)) * 100,
                    y: 100 - ((d.projectedBalance - min) / range) * 100,
                    balance: d.projectedBalance,
                    date: d.date,
                }) satisfies IChartPoint,
        );
    });

    /**
     * Generates the SVG path 'd' attribute for the line.
     */
    readonly pathData = computed((): string => {
        const pts: Array<IChartPoint> = this.points();
        if (pts.length < 2) return '';
        return pts.reduce(
            (path: string, p: IChartPoint, i: number): string =>
                i === 0 ? `M ${p.x} ${p.y}` : `${path} L ${p.x} ${p.y}`,
            '',
        );
    });

    /**
     * Generates the SVG path 'd' attribute for the filled area.
     */
    readonly areaPath = computed((): string => {
        const pts: Array<IChartPoint> = this.points();
        if (pts.length < 2) return '';
        return `${this.pathData()} L 100 100 L 0 100 Z`;
    });

    /**
     * Whether the forecast ends higher than it starts.
     */
    readonly isUp = computed((): boolean => {
        const dataArr: Array<IProjectionDataPoint> = this.data();
        if (dataArr.length < 2) return true;
        const start: number = dataArr[0]?.projectedBalance ?? 0;
        const end: number = dataArr[dataArr.length - 1]?.projectedBalance ?? 0;
        return end >= start;
    });

    /**
     * Formatted final projected balance.
     */
    readonly formattedFinalBalance = computed((): string => {
        const dataArr: Array<IProjectionDataPoint> = this.data();
        const end: number = dataArr[dataArr.length - 1]?.projectedBalance ?? 0;
        return Money.formatCurrency(end);
    });

    /**
     * Formatted delta between start and end.
     */
    readonly formattedDelta = computed((): string => {
        const dataArr: Array<IProjectionDataPoint> = this.data();
        if (dataArr.length < 2) return '$0.00';
        const start: number = dataArr[0]?.projectedBalance ?? 0;
        const end: number = dataArr[dataArr.length - 1]?.projectedBalance ?? 0;
        return Money.formatCurrency(Math.abs(end - start));
    });

    /**
     * Formatted end date of the projection.
     */
    readonly formattedEndDate = computed((): string => {
        const dataArr: Array<IProjectionDataPoint> = this.data();
        if (dataArr.length === 0) return '';
        const end: IProjectionDataPoint | undefined = dataArr[dataArr.length - 1];
        if (!end) return '';
        return new Date(end.date).toLocaleDateString(undefined, {
            month: 'short',
            day: 'numeric',
        });
    });
}

import { environment } from '../../../environments/environment';
import { GDriveAuthError, notifyAuthFailure } from './errors';

const DRIVE_API_BASE: string = 'https://www.googleapis.com/drive/v3';
const UPLOAD_API_BASE: string = 'https://www.googleapis.com/upload/drive/v3';

/**
 * Get the environment-specific suffix for filenames
 */
function getEnvSuffix(): string {
    if (environment.appEnv === 'production') return '';
    return `-${environment.appEnv}`;
}

const DB_FILENAME: string = `path-logic-ledger${getEnvSuffix()}.db.enc`;
const LOCK_FILENAME: string = `sync-lock${getEnvSuffix()}.json`;

/**
 * Helper to handle GDrive API response errors
 */
async function handleResponseError(response: Response, defaultMessage: string): Promise<never> {
    let errorMessage = `${defaultMessage}: ${response.status} ${response.statusText}`;
    try {
        const errorData = await response.json();
        errorMessage += ` - ${JSON.stringify(errorData)}`;
    } catch {
        // Ignore parse error
    }

    if (response.status === 401 || response.status === 403) {
        notifyAuthFailure(response.status);
        throw new GDriveAuthError(errorMessage, response.status);
    }
    throw new Error(errorMessage);
}

export interface ILockStatus {
    clientId: string;
    deviceName: string;
    issuedAt: string;
    expiresAt: string;
    status: 'merging';
}

export interface IDriveFile {
    id: string;
    name: string;
    modifiedTime: string;
}

/**
 * Find the encrypted database file in appDataFolder
 */
export async function findDatabaseFile(accessToken: string): Promise<IDriveFile | null> {
    const response: Response = await fetch(
        `${DRIVE_API_BASE}/files?spaces=appDataFolder&q=name='${DB_FILENAME}'`,
        {
            headers: {
                Authorization: `Bearer ${accessToken}`,
            },
        },
    );

    if (!response.ok) {
        await handleResponseError(response, 'Failed to list files');
    }

