const SCHEMA_DDL = `
    CREATE TABLE IF NOT EXISTS accounts (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        type TEXT NOT NULL,
        institutionName TEXT NOT NULL,
        isActive INTEGER NOT NULL DEFAULT 1,
        deletedAt TEXT,
        isDeleted INTEGER NOT NULL DEFAULT 0,
        clientId TEXT,
        createdAt TEXT NOT NULL,
        updatedAt TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS loan_details (
        account_id TEXT PRIMARY KEY,
        original_amount INTEGER NOT NULL,
        interest_rate REAL NOT NULL,
        term_months INTEGER NOT NULL,
        monthly_payment INTEGER NOT NULL,
        payment_due_day INTEGER NOT NULL,
        start_date TEXT NOT NULL,
        metadata TEXT,
        isDeleted INTEGER NOT NULL DEFAULT 0,
        clientId TEXT,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL,
        FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS payees (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        address TEXT,
        city TEXT,
        state TEXT,
        zipCode TEXT,
        latitude REAL,
        longitude REAL,
        website TEXT,
        phone TEXT,
        notes TEXT,
        defaultCategoryId TEXT,
        isDeleted INTEGER NOT NULL DEFAULT 0,
        clientId TEXT,
        createdAt TEXT NOT NULL,
        updatedAt TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS categories (
        id TEXT PRIMARY KEY,
        parentId TEXT,
        name TEXT NOT NULL,
        description TEXT,
        isActive INTEGER NOT NULL DEFAULT 1,
        isDeleted INTEGER NOT NULL DEFAULT 0,
        clientId TEXT,
        createdAt TEXT NOT NULL,
        updatedAt TEXT NOT NULL,
        FOREIGN KEY (parentId) REFERENCES categories(id) ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS transactions (
        id TEXT PRIMARY KEY,
        accountId TEXT NOT NULL,
        payeeId TEXT NOT NULL,
        date TEXT NOT NULL,
        payee TEXT NOT NULL,
        memo TEXT NOT NULL,
        totalAmount INTEGER NOT NULL,
        status TEXT NOT NULL,
        checkNumber TEXT,
        importHash TEXT NOT NULL,
        isDeleted INTEGER NOT NULL DEFAULT 0,
        clientId TEXT,
        createdAt TEXT NOT NULL,
        updatedAt TEXT NOT NULL,
        FOREIGN KEY (accountId) REFERENCES accounts(id),
        FOREIGN KEY (payeeId) REFERENCES payees(id)
    );

    CREATE TABLE IF NOT EXISTS splits (
        id TEXT PRIMARY KEY,
        transactionId TEXT NOT NULL,
        categoryId TEXT,
        memo TEXT,
        amount INTEGER NOT NULL,
        isDeleted INTEGER NOT NULL DEFAULT 0,
        clientId TEXT,
        updatedAt TEXT NOT NULL,
        FOREIGN KEY (transactionId) REFERENCES transactions(id) ON DELETE CASCADE,
        FOREIGN KEY (categoryId) REFERENCES categories(id)
    );

    CREATE INDEX IF NOT EXISTS idx_transactions_date ON transactions(date);
    CREATE INDEX IF NOT EXISTS idx_transactions_account ON transactions(accountId);
    CREATE INDEX IF NOT EXISTS idx_transactions_payee ON transactions(payeeId);
    CREATE INDEX IF NOT EXISTS idx_splits_transaction ON splits(transactionId);
    CREATE INDEX IF NOT EXISTS idx_splits_category ON splits(categoryId);
    CREATE INDEX IF NOT EXISTS idx_loan_details_account ON loan_details(account_id);

    CREATE TABLE IF NOT EXISTS user_settings (
        key TEXT PRIMARY KEY,
        value TEXT NOT NULL,
        updatedAt TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS sync_metadata (
        key TEXT PRIMARY KEY,
        value TEXT NOT NULL,
        updatedAt TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS recurring_schedules (
        id TEXT PRIMARY KEY,
        accountId TEXT NOT NULL,
        payee TEXT NOT NULL,
        amount INTEGER NOT NULL,
        type TEXT NOT NULL,
        frequency TEXT NOT NULL,
        paymentMethod TEXT NOT NULL,
        startDate TEXT NOT NULL,
        endDate TEXT,
        nextDueDate TEXT NOT NULL,
        lastOccurredDate TEXT,
        memo TEXT NOT NULL,
        autoPost INTEGER NOT NULL DEFAULT 0,
        isActive INTEGER NOT NULL DEFAULT 1,
        isDeleted INTEGER NOT NULL DEFAULT 0,
        clientId TEXT,
        createdAt TEXT NOT NULL,
        updatedAt TEXT NOT NULL,
        FOREIGN KEY (accountId) REFERENCES accounts(id)
    );

    CREATE TABLE IF NOT EXISTS recurring_splits (
        id TEXT PRIMARY KEY,
        scheduleId TEXT NOT NULL,
        categoryId TEXT,
        memo TEXT,
        amount INTEGER NOT NULL,
        isDeleted INTEGER NOT NULL DEFAULT 0,
        clientId TEXT,
        updatedAt TEXT NOT NULL,
        FOREIGN KEY (scheduleId) REFERENCES recurring_schedules(id) ON DELETE CASCADE,
        FOREIGN KEY (categoryId) REFERENCES categories(id)
    );
`;

