            updatedAt: '2024-03-01T00:00:00Z',
        },
    ] as any),
    categories: signal([
        {
            id: 'cat-1',
            name: 'Groceries',
            parentId: null,
            isActive: true,
        },
        {
            id: 'cat-2',
