(
    syncStatus: string,
    authError: boolean,
    isSyncing: boolean,
    lastSyncTime: number,
) => {
    return [
        {
            provide: LedgerStore,
            useValue: {
                syncStatus: signal(syncStatus),
                authError: signal(authError),
                hasLocalFallback: signal(true),
            },
        },
        {
            provide: SyncService,
            useValue: {
                isSyncing: signal(isSyncing),
                getSyncStatus: () => ({ lastSyncTime }),
            },
        },
        {
            provide: AuthService,
            useValue: {
                signInWithGoogle: async () => console.log('Mock signInWithGoogle called'),
            },
        },
    ];
}

