(): boolean | UrlTree => {
    if (environment.e2e) {
        return true;
    }

    const auth: AuthService = inject(AuthService);
    const router: Router = inject(Router);

    if (auth.isLoggedIn()) {
        return true;
    }

    return router.createUrlTree(['/sign-in']);
}

